UPDATE `dbxdb`.`emailtemplates` SET `TemplateText` = '<html><head></head><body>    <table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#FFFFFF\">        <tbody>            <tr>                <td                    style=\"width: 100%; vertical-align: middle; text-align: left; padding: 14px 24px; border-bottom: 3px solid #0A78D1; font-family: sans-serif; font-weight: 400;\">                    <img style=\"display: inline-blaock; float: left; vertical-align: middle; width: 200px;\"                        src=\"https://www.temenos.com/wp-content/themes/temenos/dist/svg/temenos-logo.svg\" alt=\"logo\"></td>            </tr>            <tr>                <td                    style=\"width: 100%; vertical-align: middle; text-align: left; padding: 25px 23px 0 23px; font-family: sans-serif; font-weight: 400;\">                    <span                        style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">Welcome</span><span                        style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">&nbsp;</span><span                        style=\"font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;\">%FirstName%                        %LastName%!!</span></td>            </tr>            <tr>                <td                    style=\"width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;\">                    <span                        style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">We                        are pleased to inform you that your application has been received successfully for a <strong>%ProductName%</strong></span></td>            </tr>   